// Shape of catalog.json, generated by tools/build_catalog.ts from the site's data files.
// Shekels are the home currency; the others were added on 12.11.2026 (owner: prices in more currencies, round numbers).
export type Currency = "ils" | "usd" | "cad" | "eur" | "gbp" | "aud";
// An item's hand-rounded price in each currency other than shekels (tools/currency_prices.json).
export type CurrencyPrices = Partial<Record<Currency, number>>;

export interface CatalogProduct {
  n: number;
  type: string;
  title: string;
  description: string;
  price: number;
  usd?: number;
  prices?: CurrencyPrices;
  langs: string[];
  titles: Record<string, string>;
  includes?: string[];
}
// describeOnCheckout: the payment page shows the plan's description, not only its name (owner 05.11.2026, the editing course).
export interface CatalogPlan { title: string; titles: Record<string, string>; description: string; price: number; usd?: number; prices?: CurrencyPrices; period: "week" | "month"; trialDays: number; describeOnCheckout?: boolean }
export interface Business { name: string; id: string; addr: string; email: string }
export interface Catalog {
  langs: string[];
  defaultLang: string;
  homeCurrencyLang: string;
  currencies: Currency[]; // every currency the site may ask to be charged in, shekels first
  bookDealMin: number;
  refundDays: number;
  business: Record<string, Business>;
  products: Record<string, CatalogProduct>;
  plans: Record<string, CatalogPlan>;
}
